#!/usr/bin/env bash
# ==============================================================================
# Antigravity Production Self-Extracting Installer
# Ultra-compact one-click installer for Antigravity Agent OS (~1.3 MB)
# ==============================================================================

set -euo pipefail

C_RESET='\033[0m'
C_BOLD='\033[1m'
C_GREEN='\033[32m'
C_BLUE='\033[34m'
C_CYAN='\033[36m'
C_YELLOW='\033[33m'
C_RED='\033[31m'
C_DIM='\033[2m'

print_banner() {
    echo -e "${C_CYAN}${C_BOLD}"
    echo "============================================================"
    echo " ðŸš€ Antigravity Supercoder OS Installer"
    echo "============================================================"
    echo -e "${C_RESET}"
}

usage() {
    echo -e "${C_BOLD}Usage:${C_RESET} $0 [OPTIONS]"
    echo ""
    echo -e "${C_BOLD}Options:${C_RESET}"
    echo "  -a, --all               Install both Local (.agents/) and Global (~/.gemini/config/)"
    echo "  -g, --global            Install Global configuration only (~/.gemini/config/)"
    echo "  -l, --local             Install Local workspace (.agents/) in current directory"
    echo "  -t, --target <DIR>      Install Local workspace (.agents/) into specified directory"
    echo "  -y, --yes               Non-interactive mode (auto-accept prompts)"
    echo "  --dry-run               Simulate installation without making changes"
    echo "  -h, --help              Show this help message"
    echo ""
    echo -e "${C_BOLD}Interactive Mode:${C_RESET}"
    echo "  Run without arguments to launch the interactive setup menu."
    echo ""
}

TARGET_MODE=""
TARGET_DIR="$(pwd)"
AUTO_YES=false
DRY_RUN=false

while [[ $# -gt 0 ]]; do
    case "$1" in
        -a|--all)
            TARGET_MODE="all"
            shift
            ;;
        -g|--global)
            TARGET_MODE="global"
            shift
            ;;
        -l|--local)
            TARGET_MODE="local"
            shift
            ;;
        -t|--target)
            TARGET_MODE="custom"
            TARGET_DIR="$2"
            shift 2
            ;;
        -y|--yes)
            AUTO_YES=true
            shift
            ;;
        --dry-run)
            DRY_RUN=true
            shift
            ;;
        -h|--help)
            print_banner
            usage
            exit 0
            ;;
        *)
            echo -e "${C_RED}Unknown option: $1${C_RESET}"
            usage
            exit 1
            ;;
    esac
done

print_banner

# Interactive selection if no mode specified
if [ -z "$TARGET_MODE" ]; then
    echo -e "${C_BOLD}Select installation target:${C_RESET}"
    echo -e "  ${C_CYAN}1)${C_RESET} ${C_BOLD}Both Local & Global${C_RESET} (Full Suite: current workspace + ~/.gemini/config/)"
    echo -e "  ${C_CYAN}2)${C_RESET} ${C_BOLD}Global Only${C_RESET} (~/.gemini/config/)"
    echo -e "  ${C_CYAN}3)${C_RESET} ${C_BOLD}Local Workspace Only${C_RESET} (.agents/ in current directory: $(pwd))"
    echo -e "  ${C_CYAN}4)${C_RESET} ${C_BOLD}Custom Workspace Directory${C_RESET}"
    echo -e "  ${C_CYAN}5)${C_RESET} Cancel / Exit"
    echo ""
    read -r -p "Enter choice [1-5] (default: 1): " user_choice
    user_choice="${user_choice:-1}"

    case "$user_choice" in
        1) TARGET_MODE="all" ;;
        2) TARGET_MODE="global" ;;
        3) TARGET_MODE="local" ;;
        4)
            TARGET_MODE="custom"
            read -r -p "Enter absolute or relative path for target workspace: " custom_path
            TARGET_DIR="$(cd "$custom_path" 2>/dev/null && pwd || echo "$custom_path")"
            ;;
        5|q|Q)
            echo "Installation cancelled."
            exit 0
            ;;
        *)
            echo -e "${C_RED}Invalid choice. Aborting.${C_RESET}"
            exit 1
            ;;
    esac
fi

echo -e "${C_BLUE}Target Scope:${C_RESET} ${C_BOLD}$TARGET_MODE${C_RESET}"
if [[ "$TARGET_MODE" == "local" || "$TARGET_MODE" == "custom" || "$TARGET_MODE" == "all" ]]; then
    echo -e "${C_BLUE}Local Workspace Target:${C_RESET} ${C_BOLD}$TARGET_DIR/.agents${C_RESET}"
fi
if [[ "$TARGET_MODE" == "global" || "$TARGET_MODE" == "all" ]]; then
    echo -e "${C_BLUE}Global Target:${C_RESET} ${C_BOLD}$HOME/.gemini/config${C_RESET}"
fi
echo ""

# 1. Dependency Checks
echo -e "${C_BOLD}ðŸ” Checking System Prerequisites...${C_RESET}"

check_cmd() {
    local cmd="$1"
    local desc="$2"
    local req="$3"
    if command -v "$cmd" >/dev/null 2>&1; then
        echo -e "  ${C_GREEN}âœ”${C_RESET} $desc ($cmd) found"
        return 0
    else
        if [ "$req" = "required" ]; then
            echo -e "  ${C_RED}âœ–${C_RESET} $desc ($cmd) NOT found (Required)"
            return 1
        else
            echo -e "  ${C_YELLOW}âš ${C_RESET} $desc ($cmd) not found (Optional)"
            return 0
        fi
    fi
}

MISSING_DEPS=0
check_cmd "tar" "Tar extraction tool" "required" || MISSING_DEPS=$((MISSING_DEPS+1))
check_cmd "xz" "XZ decompression tool" "required" || MISSING_DEPS=$((MISSING_DEPS+1))
check_cmd "python3" "Python 3.10+ runtime" "required" || MISSING_DEPS=$((MISSING_DEPS+1))
check_cmd "node" "Node.js runtime" "optional"
check_cmd "npx" "NPX package runner" "optional"
check_cmd "uv" "UV package manager" "optional"
check_cmd "docker" "Docker engine" "optional"

if command -v npm >/dev/null 2>&1; then
    npm config set allow-remote all >/dev/null 2>&1 || true
fi

if [ "$MISSING_DEPS" -gt 0 ]; then
    echo -e "\n${C_RED}âŒ Missing required system tools. Please install them and rerun.${C_RESET}"
    exit 1
fi

# 2. Extract Embedded Payload to Temp Directory
echo -e "\n${C_BOLD}ðŸ“¦ Unpacking Embedded Components...${C_RESET}"
TEMP_EXTRACT="$(mktemp -d /tmp/agy-install-XXXXXX)"
trap 'rm -rf "$TEMP_EXTRACT"' EXIT

if [ "$DRY_RUN" = true ]; then
    echo -e "${C_YELLOW}[DRY-RUN] Simulating payload extraction...${C_RESET}"
else
    ARCHIVE_LINE=$(awk '/^__ARCHIVE_PAYLOAD_BELOW__/ {print NR + 1; exit 0; }' "$0")
    tail -n +"$ARCHIVE_LINE" "$0" | tar -xJf - -C "$TEMP_EXTRACT"
    echo -e "${C_GREEN}âœ” Payload extracted to staging buffer${C_RESET}"
fi

TIMESTAMP=$(date +%Y%m%d_%H%M%S)

# 3. Perform Local Installation
if [[ "$TARGET_MODE" == "local" || "$TARGET_MODE" == "custom" || "$TARGET_MODE" == "all" ]]; then
    echo -e "\n${C_BOLD}ðŸ“‚ Installing Local Workspace Components...${C_RESET}"
    LOCAL_DEST="$TARGET_DIR/.agents"

    if [ "$DRY_RUN" = true ]; then
        echo -e "${C_YELLOW}[DRY-RUN] Would install to: $LOCAL_DEST${C_RESET}"
    else
        if [ -d "$LOCAL_DEST" ]; then
            rm -rf "$LOCAL_DEST"
        fi

        mkdir -p "$LOCAL_DEST"
        cp -a "$TEMP_EXTRACT/.agents/." "$LOCAL_DEST/"
        chmod +x "$LOCAL_DEST/scripts/"*.py 2>/dev/null || true
        chmod +x "$LOCAL_DEST/scripts/"*.sh 2>/dev/null || true
        echo -e "  ${C_GREEN}âœ” Installed rules, skills, workflows, scripts, and MCP catalog to:${C_RESET} ${C_BOLD}$LOCAL_DEST${C_RESET}"

        # Synchronize core rules and all workflows to global config one time
        GLOBAL_CONFIG="$HOME/.gemini/config"
        GLOBAL_IDE="$HOME/.gemini/antigravity-ide/global_workflows"
        mkdir -p "$GLOBAL_CONFIG/rules" "$GLOBAL_CONFIG/workflows" "$GLOBAL_IDE"
        # Enforce always_on for global rules to apply to all projects
        sed 's/trigger: model_decision/trigger: always_on/' "$TEMP_EXTRACT/.agents/rules/core.md" > "$GLOBAL_CONFIG/rules/core.md" 2>/dev/null || cp "$TEMP_EXTRACT/.agents/rules/core.md" "$GLOBAL_CONFIG/rules/" 2>/dev/null || true
        sed 's/trigger: model_decision/trigger: always_on/' "$TEMP_EXTRACT/.agents/rules/effort.md" > "$GLOBAL_CONFIG/rules/effort.md" 2>/dev/null || cp "$TEMP_EXTRACT/.agents/rules/effort.md" "$GLOBAL_CONFIG/rules/" 2>/dev/null || true
        cp -a "$TEMP_EXTRACT/.agents/workflows/." "$GLOBAL_CONFIG/workflows/" 2>/dev/null || true
        cp -a "$TEMP_EXTRACT/.agents/workflows/." "$GLOBAL_IDE/" 2>/dev/null || true
        echo -e "  ${C_GREEN}âœ” All 30 workflows & global rules active in:${C_RESET} ${C_BOLD}$GLOBAL_CONFIG${C_RESET}"
    fi
fi

# 4. Perform Global Installation
if [[ "$TARGET_MODE" == "global" || "$TARGET_MODE" == "all" ]]; then
    echo -e "\n${C_BOLD}ðŸŒ Installing Global Configuration...${C_RESET}"
    GLOBAL_DEST="$HOME/.gemini/config"

    if [ "$DRY_RUN" = true ]; then
        echo -e "${C_YELLOW}[DRY-RUN] Would install to: $GLOBAL_DEST${C_RESET}"
    else
        mkdir -p "$GLOBAL_DEST/rules" "$GLOBAL_DEST/skills" "$GLOBAL_DEST/workflows" "$GLOBAL_DEST/plugins"

        # Copy global rules, skills, workflows, and plugins
        if [ -d "$TEMP_EXTRACT/.agents/rules" ]; then
            cp -a "$TEMP_EXTRACT/.agents/rules/." "$GLOBAL_DEST/rules/" 2>/dev/null || true
        fi
        if [ -d "$TEMP_EXTRACT/.agents/skills" ]; then
            cp -a "$TEMP_EXTRACT/.agents/skills/." "$GLOBAL_DEST/skills/" 2>/dev/null || true
        fi
        if [ -d "$TEMP_EXTRACT/.agents/workflows" ]; then
            cp -a "$TEMP_EXTRACT/.agents/workflows/." "$GLOBAL_DEST/workflows/" 2>/dev/null || true
            mkdir -p "$HOME/.gemini/antigravity-ide/global_workflows"
            cp -a "$TEMP_EXTRACT/.agents/workflows/." "$HOME/.gemini/antigravity-ide/global_workflows/" 2>/dev/null || true
        fi
        if [ -d "$TEMP_EXTRACT/.agents/plugins" ]; then
            cp -a "$TEMP_EXTRACT/.agents/plugins/." "$GLOBAL_DEST/plugins/" 2>/dev/null || true
        fi

        # Ensure zero-default clean profile
        if [ ! -f "$GLOBAL_DEST/mcp_config.json" ]; then
            echo '{"mcpServers": {}}' > "$GLOBAL_DEST/mcp_config.json"
        fi
        echo -e "  ${C_GREEN}âœ” Global configuration installed to:${C_RESET} ${C_BOLD}$GLOBAL_DEST${C_RESET}"
    fi
fi

# 5. MCP Runner & PATH Configuration
echo -e "\n${C_BOLD}ðŸ”Œ Configuring MCP Tools & Runtime Environment...${C_RESET}"
BIN_DIR="$HOME/.local/bin"

if [ "$DRY_RUN" = true ]; then
    echo -e "${C_YELLOW}[DRY-RUN] Would configure MCP runner in $BIN_DIR/mcp-npx and PATH${C_RESET}"
else
    mkdir -p "$BIN_DIR"

    # Install mcp-npx runner
    if [ -f "$TEMP_EXTRACT/.agents/scripts/mcp_runner.sh" ]; then
        cp "$TEMP_EXTRACT/.agents/scripts/mcp_runner.sh" "$BIN_DIR/mcp-npx"
        chmod +x "$BIN_DIR/mcp-npx"
        echo -e "  ${C_GREEN}âœ” Installed clean MCP runner to:${C_RESET} $BIN_DIR/mcp-npx"
    fi

    # Ensure ~/.local/bin is in PATH for bash/zsh
    PATH_EXPORT='export PATH="$HOME/.local/bin:$PATH"'
    for RC_FILE in "$HOME/.bashrc" "$HOME/.zshrc"; do
        if [ -f "$RC_FILE" ] && ! grep -q '.local/bin' "$RC_FILE"; then
            echo -e "\n# Added by Antigravity Installer\n$PATH_EXPORT" >> "$RC_FILE"
            echo -e "  ${C_GREEN}âœ” Added ~/.local/bin to PATH in:${C_RESET} $RC_FILE"
        fi
    done
fi

# 6. Post-Installation Health Verification
echo -e "\n${C_BOLD}âœ¨ Verifying Installation Health...${C_RESET}"
if [ "$DRY_RUN" = true ]; then
    echo -e "${C_YELLOW}[DRY-RUN] Verification skipped in dry-run mode.${C_RESET}"
else
    python3 - << 'VERIFY_EOF'
import os, sys, json, glob

errors = []
print("  Running post-install checks...")

# Check MCP Catalog
reg_path = ".agents/mcp-registry/servers.json"
if os.path.exists(reg_path):
    try:
        with open(reg_path) as f:
            data = json.load(f)
            count = len(data.get("mcpServers", {}))
            print(f"    âœ” Validated MCP Catalog ({count} verified servers available on-demand)")
    except Exception as e:
        errors.append(f"Invalid JSON in {reg_path}: {e}")

# Check Rules & Workflows
rules = glob.glob(".agents/rules/*.md")
workflows = glob.glob(".agents/workflows/*.md")
print(f"    âœ” {len(rules)} Rules and {len(workflows)} Workflows available")

if errors:
    print(f"\n  âŒ Post-install check encountered {len(errors)} issues:")
    for err in errors:
        print(f"     - {err}")
    sys.exit(1)
else:
    print("    âœ” All configuration files, scripts, and MCP catalog verified clean!")
VERIFY_EOF
fi

echo -e "\n${C_GREEN}${C_BOLD}============================================================"
echo " ðŸŽ‰ Antigravity Installation Complete!"
echo "============================================================"
echo -e "${C_RESET}"
echo -e "Available Workflows & Slash Commands:"
echo -e "  ${C_CYAN}/build-feature${C_RESET}  - 5-Stage Supercoder Engine"
echo -e "  ${C_CYAN}/learn${C_RESET}          - 2-Way Mistake Immunization Engine"
echo -e "  ${C_CYAN}/mcp${C_RESET}            - Dynamic On-Demand MCP Manager"
echo -e "  ${C_CYAN}/effort${C_RESET}         - Model Reasoning Effort Override (low, mid, high, ultra)"
echo -e "  ${C_CYAN}/plan${C_RESET}           - Structured Project Planning Mode"
echo -e "  ${C_CYAN}/debug${C_RESET}          - Root-Cause Debugging & Investigation"
echo -e "  ${C_CYAN}/test${C_RESET}           - AAA Test Generation & Verification"
echo -e "  ${C_CYAN}/design-ui${C_RESET}       - Design Intelligence & Layouts"
echo -e "  ${C_CYAN}/focus-adhd${C_RESET}     - Action-first, bounded cognitive output mode"
echo -e "  ${C_CYAN}/humanize-text${C_RESET}  - Human voice preservation & AI slop removal"
echo -e "  ${C_CYAN}/compress-tokens${C_RESET}- Token-compressed telegraphic communication"
echo ""

exit 0

